      "parameters": {
        "jsCode": "// Limpia lo que llega del formulario y decide si sirve.\n// El nodo Webhook mete el cuerpo de la peticion en .body\nconst c = $input.first().json.body || $input.first().json;\n\n// Quita espacios de sobra y deja los textos manejables\nconst t = (v) => String(v == null ? '' : v).trim().replace(/\\s+/g, ' ');\nconst errores = [];\n\nconst nombre   = t(c.nombre);\nconst email    = t(c.email).toLowerCase();\nconst mensaje  = t(c.mensaje);\nconst empresa  = t(c.empresa);\nconst telefono = t(c.telefono).replace(/[^0-9+]/g, '');\n\nif (nombre.length < 2)     errores.push('nombre');\nif (mensaje.length < 10)   errores.push('mensaje_corto');\nif (mensaje.length > 2000) errores.push('mensaje_largo');\n\n// Un email de verdad: algo, arroba, algo, punto, dos letras minimo\nif (!/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(email)) errores.push('email');\n\n// Correos de usar y tirar: un lead al que no puedes contestar no es un lead\nconst dominio = email.split('@')[1] || '';\nif (['mailinator.com','yopmail.com','guerrillamail.com','10minutemail.com'].includes(dominio)) {\n  errores.push('email_desechable');\n}\n\n// Campo trampa: esta escondido fuera de la pantalla. Una persona no lo ve.\n// Si viene con texto, lo ha rellenado un robot.\nif (t(c.web) !== '') errores.push('bot');\n\nreturn [{\n  json: {\n    valido: errores.length === 0,\n    errores,\n    lead: {\n      nombre, email, empresa, telefono, mensaje, dominio,\n      origen: t(c.origen) || 'formulario-web',\n      recibido_en: new Date().toISOString()\n    }\n  }\n}];"
      },
