        "jsCode": "// Este nodo corre DESPUES de haber contestado al formulario.\n// Su unico trabajo: dejar pasar solo lo que merece la pena procesar.\nconst item = $input.first().json;\n\n// 1) Lo que no paso la validacion se queda aqui.\n//    Devolver una lista vacia detiene esta rama del flujo. Sin errores, sin drama.\nif (!item.valido) return [];\n\nconst lead = item.lead;\n\n// 2) Antirrebote. Primera capa del control de duplicados: el doble clic.\n//    $getWorkflowStaticData es la memoria del propio flujo: sobrevive\n//    entre ejecuciones mientras el flujo este ACTIVO.\nconst memoria = $getWorkflowStaticData('global');\nif (!memoria.ultimos) memoria.ultimos = {};\n\nconst ahora = Date.now();\nconst VENTANA = 60 * 1000; // 60 segundos\n\n// Tiramos lo de hace mas de 10 minutos para que la memoria no engorde\nfor (const correo of Object.keys(memoria.ultimos)) {\n  if (ahora - memoria.ultimos[correo] > 600000) delete memoria.ultimos[correo];\n}\n\nconst anterior = memoria.ultimos[lead.email];\nif (anterior && ahora - anterior < VENTANA) {\n  console.log('Rebote descartado: ' + lead.email + ' (hace ' + Math.round((ahora - anterior) / 1000) + ' s)');\n  return [];\n}\n\nmemoria.ultimos[lead.email] = ahora;\nreturn [{ json: { lead } }];"
      },
