        "jsCode": "// Junta lo que ha contestado el CRM con el lead, y escribe la pregunta para la IA.\nconst busqueda = $input.first().json;\n\n// Para mirar hacia atras en el flujo se llama al nodo por su nombre\nconst lead = $('Filtro').first().json.lead;\n\nconst encontrados = busqueda.results || [];\nconst existe = encontrados.length > 0;\nconst ficha = existe ? encontrados[0] : null;\n\n// Segunda capa del control de duplicados: ¿ya estaba en el CRM y desde cuando?\nlet dias_desde_alta = null;\nif (existe && ficha.properties && ficha.properties.createdate) {\n  dias_desde_alta = Math.round((Date.now() - new Date(ficha.properties.createdate).getTime()) / 86400000);\n}\n\n// Las instrucciones fijas: lo que la IA tiene que hacer siempre, con este lead o con otro\nconst sistema = [\n  'Eres el filtro de entrada del equipo comercial de una empresa espanola que vende software de gestion a pymes.',\n  'Lees un mensaje de un formulario web y devuelves SOLO un objeto JSON. Nada de texto alrededor.',\n  'Campos exactos:',\n  '- temperatura: \"caliente\" si pide precio, demo o reunion, o dice para cuando lo necesita. \"templado\" si pregunta cosas concretas sin prisa. \"frio\" si es curiosidad, estudiante o mensaje vago.',\n  '- interes: uno de \"precio\", \"demo\", \"soporte\", \"colaboracion\", \"empleo\", \"spam\".',\n  '- resumen: maximo 20 palabras, en espanol, que pide y para que.',\n  '- urgencia: numero del 1 al 5. Un 5 solo si da una fecha concreta o dice que corre prisa.',\n  '- idioma: dos letras del idioma del mensaje (\"es\", \"en\", \"ca\").',\n  'Si el mensaje es publicidad, criptomonedas, posicionamiento web barato o cualquier cosa que no sea un cliente potencial: interes \"spam\" y temperatura \"frio\".'\n].join('\\n');\n\n// Los datos de este lead concreto\nconst pregunta = [\n  'Nombre: ' + lead.nombre,\n  'Email: ' + lead.email,\n  'Dominio del correo: ' + lead.dominio,\n  'Empresa: ' + (lead.empresa || 'no la dice'),\n  'Telefono: ' + (lead.telefono || 'no lo deja'),\n  'Ya estaba en el CRM: ' + (existe ? 'si, desde hace ' + dias_desde_alta + ' dias' : 'no, es nuevo'),\n  'Mensaje:',\n  lead.mensaje\n].join('\\n');\n\nreturn [{\n  json: {\n    lead,\n    duplicado: existe,\n    contacto_id: existe ? ficha.id : null,\n    dias_desde_alta,\n    sistema,\n    pregunta\n  }\n}];"
