    {
      "parameters": {
        "jsCode": "// Lee lo que ha contestado la IA y lo deja utilizable pase lo que pase.\nconst r = $input.first().json;\nconst previo = $('Duplicado').first().json;\n\n// La respuesta de la API viene dentro de content[0].text\nconst bruto = String(r && r.content && r.content[0] ? r.content[0].text : '');\n\n// Nos quedamos con lo que hay entre la primera llave y la ultima.\n// Asi da igual si la IA saluda antes o envuelve el JSON en marcas de codigo.\nconst ini = bruto.indexOf('{');\nconst fin = bruto.lastIndexOf('}');\nlet ia = null;\nif (ini !== -1 && fin > ini) {\n  try { ia = JSON.parse(bruto.slice(ini, fin + 1)); } catch (e) { ia = null; }\n}\n\n// Nunca nos fiamos de lo que devuelve un modelo: lo comparamos con la lista cerrada\n// de valores que el CRM sabe leer. Si no encaja, valor por defecto y seguimos.\nconst temps = ['caliente', 'templado', 'frio'];\nconst ints  = ['precio', 'demo', 'soporte', 'colaboracion', 'empleo', 'spam'];\nconst num   = Number(ia && ia.urgencia);\n\nconst clasificacion = {\n  temperatura: ia && temps.includes(ia.temperatura) ? ia.temperatura : 'templado',\n  interes:     ia && ints.includes(ia.interes)      ? ia.interes     : 'soporte',\n  resumen:     String(ia && ia.resumen ? ia.resumen : previo.lead.mensaje).slice(0, 200),\n  urgencia:    Number.isFinite(num) ? Math.min(5, Math.max(1, Math.round(num))) : 3,\n  idioma:      ia && /^[a-z]{2}$/.test(String(ia.idioma)) ? ia.idioma : 'es',\n  la_dijo_la_ia: ia !== null\n};\n\n// Object.assign copia lo de antes y le anade la clasificacion\nreturn [{ json: Object.assign({}, previo, { clasificacion }) }];"
      },
